export interface MusicalTourDate {
  city: string;
  venue: string;
  startDate: string; // Format: "YYYY-MM-DD"
  endDate?: string; // Format: "YYYY-MM-DD" (optional – wenn nicht gesetzt, kein Enddatum anzeigen)
  premiereDate?: string; // Format: "YYYY-MM-DD" (optional – Premiere-Datum für Icon-Anzeige in der Box)
  eventimUrl: string;
  oeticketUrl?: string;
  badge?: string; // z.B. "5 Wochen Gastspiel"
  displayLabel?: string; // Optionaler Anzeigetext statt Datum, z.B. "Spielzeit 2026/2027"
}

export interface MusicalQuote {
  text: string;
  source: string; // z.B. "Die Welt", "Der Spiegel"
}

export interface MusicalGalleryImage {
  url: string;
  alt: string;
}

export interface MusicalShowFact {
  label: string;
  value: string;
}

export interface MusicalFAQ {
  question: string;
  answer: string;
}

export interface MusicalSale {
  label: string;
  discount: string;
  note?: string;
  validUntil?: string; // Format: "YYYY-MM-DD"; ohne Datum bleibt der Sale aktiv
}

export interface Musical {
  id: string;
  slug: string;
  title: string;
  subtitle?: string;
  provider: string;
  category: "ensuite" | "fester-standort" | "tournee" | "kinder"; // Legacy, wird durch categories ersetzt
  categories?: Array<"fester-standort" | "tournee" | "erwachsene" | "familie" | "kinder">;
  city?: string;
  cities?: string[];
  headerCities?: string[]; // Die wichtigsten Städte für die Header-Anzeige (z.B. die 10 größten)
  venue?: string;
  venuePerCity?: Record<string, string>; // Venue-Name pro Stadt, z.B. { "Hamburg": "Theater am Großmarkt", "Köln": "Musical Dome Köln" }
  description: string;
  detailHeadline?: string; // Headline auf der Detail-Seite (z.B. "DER GRAF KEHRT ZURÜCK")
  detailDescription?: string; // Ausführliche Beschreibung auf der Detail-Seite
  image: string;
  heroImage?: string; // Alternatives Hero-Bild für die Detailseite (z.B. Galerie-Bild statt Teaser)
  keyvisual?: string; // Quadratisches Bild für Detail-Seite
  keyvisualLink?: string; // Optionaler eigener Link für das Keyvisual (überschreibt den Standard-Ticket-Link)
  ticketCtaUrl?: string; // Optionaler eigener Link für den roten "Tickets sichern"-Button
  awinHeroUrl?: string; // Awin-Link für den Gold-Ghost-Button oben (mit clickref=...-hero)
  awinStickyUrl?: string; // Awin-Link für den Sticky-Footer-Button (mit clickref=...-sticky)
  awinBoxUrl?: string; // Awin-Link für den roten CTA-Kasten (mit clickref=...-box)
  priceFrom?: string; // Mindestpreis z.B. "40,40"
  youtubeTrailerId?: string; // YouTube Video ID (z.B. "dQw4w9WgXcQ")
  eventimUrl: string;
  featured?: boolean;
  tags: string[];
  sale?: MusicalSale; // Optionaler Angebots-Störer auf Teaser-Karten
  // Neue Felder für Detail-Seite
  tourDates?: MusicalTourDate[];
  quotes?: MusicalQuote[];
  gallery?: MusicalGalleryImage[];
  showFacts?: MusicalShowFact[];
  storyHeadline?: string; // Headline für Story-Bereich
  storyText?: string; // Story-Text für Detail-Seite
  faqItems?: MusicalFAQ[];
  uspItems?: Array<{ icon: string; title: string; text: string }>;
  seoTitle?: string; // Individueller <title> für die Detailseite
  seoDescription?: string; // Individuelle <meta description> für die Detailseite
}

export interface City {
  slug: string;
  name: string;
  image: string;
  description: string;
  musicalCount: number;
  hotelSearchUrl: string;
}

export interface Provider {
  name: string;
  slug: string;
  description: string;
  website: string;
  logo?: string; // Logo URL
}

// AWIN Deeplink-Funktion: Merchant ID 11388 (Eventim)
// Format: https://www.awin1.com/cread.php?awinmid=11388&awinaffid=YOUR_ID&ued=ENCODED_URL
// Hinweis: Publisher-ID muss nach AWIN-Registrierung eingesetzt werden
export const AWIN_MERCHANT_ID = "11388";
export const AWIN_PUBLISHER_ID = "2865727"; // Awin Publisher-ID

export function createAwinLink(destinationUrl: string): string {
  const encodedUrl = encodeURIComponent(destinationUrl);
  return `https://www.awin1.com/cread.php?awinmid=${AWIN_MERCHANT_ID}&awinaffid=${AWIN_PUBLISHER_ID}&ued=${encodedUrl}`;
}

