// Hilfsfunktionen
// Hilfsfunktionen
export function getMusicalBySlug(slug: string): Musical | undefined {
  return musicals.find((m) => m.slug === slug);
}

// Liste der aktiv freigeschalteten Musical-IDs/Slugs
// Hier eintragen, wenn ein neues Musical live geht
export const ACTIVE_MUSICAL_IDS = ["dracula", "moulinrouge", "phantom-der-oper", "fack-ju-goehte", "dreihaselnuesse", "sister-act", "rapunzel", "schoene-und-das-biest", "gloeckner-von-notre-dame", "starlight-express", "eiskoenigin", "koenig-der-loewen", "mj-musical", "tarzan", "ziz", "teufel-traegt-prada", "wir-sind-am-leben", "tanz-der-vampire", "we-will-rock-you", "salon-rosie", "und-julia"];

export function getActiveMusicals(): Musical[] {
  return musicals.filter((m) => ACTIVE_MUSICAL_IDS.includes(m.id) || ACTIVE_MUSICAL_IDS.includes(m.slug));
}

export function getMusicalsByCity(cityName: string): Musical[] {
  return musicals.filter((m) => m.city === cityName || m.cities?.includes(cityName));
}

export function hasActiveTourDateForCity(musical: Musical, cityName: string): boolean {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  if (musical.tourDates && musical.tourDates.length > 0) {
    // Musical has tour dates: check if any date for this city is still active (endDate >= today)
    return musical.tourDates.some(
      (td) => td.city === cityName && td.endDate != null && new Date(td.endDate) >= today
    );
  }
  // No tour dates defined: fall back to city field match (always show)
  return musical.city === cityName || (musical.cities?.includes(cityName) ?? false);
}

export function getActiveMusicalsByCity(cityName: string): Musical[] {
  return getActiveMusicals().filter((m) => {
    const matchesCity = m.city === cityName || m.cities?.includes(cityName);
    if (!matchesCity) return false;
    return hasActiveTourDateForCity(m, cityName);
  });
}

export function getActiveMusicalCountByCity(cityName: string): number {
  return getActiveMusicalsByCity(cityName).length;
}

export function getCityBySlug(slug: string): City | undefined {
  return cities.find((c) => c.slug === slug);
}

export function getProviderBySlug(slug: string): Provider | undefined {
  return providers.find((p) => p.slug === slug);
}

export function getFeaturedMusicals(): Musical[] {
  const featured = musicals.filter((m) => m.featured === true);
  // Feste Reihenfolge: König der Löwen, Eiskönigin, Dracula, Moulin Rouge, dann Rest
  const ORDER = ['koenig-der-loewen', 'eiskoenigin', 'dracula', 'moulinrouge'];
  const ordered = ORDER.map((id) => featured.find((m) => m.id === id)).filter(Boolean) as Musical[];
  const rest = featured.filter((m) => !ORDER.includes(m.id));
  return [...ordered, ...rest];
}
